#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> p1(3), p2(3);
    for (int i = 0; i < 3; i++) cin >> p1[i];
    for (int i = 0; i < 3; i++) cin >> p2[i];

    int wins = 0;
    vector<int> p2_extended = p2;
    p2_extended.push_back(p2[0]);
    for (int i = 0; i < 3; i++) {
        wins += min(p1[i], p2_extended[i + 1]);
    }
    p2_extended.pop_back();
    // Rotate p2 to the right by one position
    int last = p2.back();
    for (int i = 2; i > 0; i--) {
        p2[i] = p2[i - 1];
    }
    p2[0] = last;

    for (int i = 0; i < 3; i++) {
        if (p1[i] > 0) {
            int min_val = min(p1[i], p2[i]);
            p1[i] -= min_val;
            p2[i] -= min_val;
            if (p1[i] > 0) {
                int min_val2 = min(p1[i], p2[(i + 1) % 3]);
                p1[i] -= min_val2;
                p2[(i + 1) % 3] -= min_val2;
            }
        }
    }
    cout << p1[0] + p1[1] + p1[2] << " " << wins << "\n";
    return 0;
}

